#!/usr/bin/env python3
# Temporary installer for the unified CTR fit refactor.
# Keep this script outside the repository (or delete it after application).
from __future__ import annotations

import argparse
import base64
import json
import re
from pathlib import Path

PAYLOADS = {'compare_pico_waveform_ctr.py': '', 'utils_fit/plotting.py': '', 'utils_fit/__init__.py': '', 'utils_fit/io.py': '', 'utils_fit/gaussian.py': ''}

R = {'analyze_imports_old': 'PROJECT = Path(__file__).resolve().parents[1]\nif str(PROJECT) not in sys.path:\n    sys.path.insert(0, str(PROJECT))\nfrom utils.config import config_copy, load_config\nfrom utils.fit import FitResult, choose_best, scan_timing_grid\n', 'analyze_imports_new': 'PROJECT = Path(__file__).resolve().parents[1]\nREPO_ROOT = PROJECT.parent\nif str(REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(REPO_ROOT))\nif str(PROJECT) not in sys.path:\n    sys.path.insert(0, str(PROJECT))\nfrom utils.config import config_copy, load_config\nfrom utils_fit import FitResult, choose_best, scan_timing_grid\nfrom utils_fit.plotting import plot_gaussian_fit\n', 'metrics_import_old': 'from typing import Any\n\nimport numpy as np\n\nfrom utils.fit import FitResult, fit_delta_times_integer_fs\n', 'metrics_import_new': 'from pathlib import Path\nimport sys\nfrom typing import Any\n\nimport numpy as np\n\n_REPO_ROOT = Path(__file__).resolve().parents[2]\nif str(_REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(_REPO_ROOT))\n\nfrom utils_fit import FitResult, fit_delta_times_ps\n', 'metrics_fit_new': 'def fit_times_ps(values_ps: np.ndarray, method: str, fit_config: dict[str, Any]) -> FitResult:\n    values = np.asarray(values_ps, dtype=np.float64).reshape(-1)\n    return fit_delta_times_ps(\n        values,\n        method=method,\n        parameter=0.0,\n        n_total=int(values.size),\n        n_selected=int(values.size),\n        config=fit_config,\n    )\n\n', 'janus_import_old': 'import math\nimport time\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\n', 'janus_import_new': 'import math\nimport time\nfrom pathlib import Path\nimport sys\nfrom typing import Any\n\nimport numpy as np\n\n_REPO_ROOT = Path(__file__).resolve().parents[2]\nif str(_REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(_REPO_ROOT))\n\nfrom utils_fit import fit_delta_times_ps\nfrom utils_fit.io import load_fit_csv, write_fit_csv\nfrom utils_fit.plotting import plot_gaussian_fit\n', 'janus_summary_new': 'def _summary_row(run, run_info, fit, toa_lsb_ps: float | None, average_delay_corrected_alignments: int) -> dict[str, Any]:\n    del toa_lsb_ps  # FitResult is already expressed in ps.\n    row: dict[str, Any] = {\n        "run_id": run.run_id,\n        "Voltage": run.voltage,\n        "AcquisitionMode": run_info.acquisition_mode,\n        "E_th": run_info.energy_threshold_mv,\n        "T_th": run_info.timing_threshold_mv,\n        "fit_metric": "common_bin_integrated_gaussian_all_events",\n        "gaussian_area_events": _number(fit.n_fit),\n        "gaussian_area_error_events": "",\n        "gaussian_mean_ps": _number(fit.mean_ps),\n        "gaussian_mean_error_ps": _number(fit.mean_error_ps),\n        "gaussian_sigma_ps": _number(fit.sigma_ps),\n        "gaussian_sigma_error_ps": _number(fit.sigma_error_ps),\n        "CTR_ps": _number(fit.ctr_ps),\n        "CTR_error_ps": _number(fit.ctr_error_ps),\n        "average_delay_corrected_alignments": int(average_delay_corrected_alignments),\n    }\n    return row\n', 'janus_fit_old': '                fit = fit_timing(\n                    measurements.timing_lsb[selection.final_mask],\n                    cfg["fit"],\n                )\n', 'janus_fit_new': '                timing_ps = (\n                    measurements.timing_lsb[selection.final_mask].astype(np.float64)\n                    * float(toa_lsb_ps)\n                )\n                fit = fit_delta_times_ps(\n                    timing_ps,\n                    method="Pico-TDC LED",\n                    parameter=float(run_info.timing_threshold_mv),\n                    n_total=int(measurements.size),\n                    n_selected=int(np.count_nonzero(selection.final_mask)),\n                    config=cfg["fit"],\n                )\n                if not fit.success:\n                    raise RuntimeError(f"Common Gaussian fit failed: {fit.message}")\n', 'janus_plot_old': '                    plot_timing_fit(\n                        timing_plot_path,\n                        run.run_id,\n                        fit,\n                        toa_lsb_ps,\n                        cfg,\n                    )\n', 'janus_plot_new': '                    plot_gaussian_fit(\n                        fit,\n                        timing_plot_path,\n                        dpi=int(cfg["plots"]["dpi"]),\n                        title=f"{run.run_id} — Pico-TDC timing fit",\n                        xlabel="ch7 − ch3 [ps]",\n                    )\n'}

COMMON_FIT_CONFIG = {'min_events': 100, 'adaptive_binning': {'enabled': True, 'bins_per_fwhm': 10.0, 'min_bin_ps': 1.0, 'max_bin_ps': 25.0, 'phase_count': 8}}


def _replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(
            f"{path}: expected exactly one match, got {count}. "
            "Repository may have changed since the patch was generated."
        )
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def _regex_once(path: Path, pattern: str, replacement: str) -> None:
    text = path.read_text(encoding="utf-8")
    updated, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(
            f"{path}: regex expected one match, got {count}: {pattern}"
        )
    path.write_text(updated, encoding="utf-8")


def _write_payloads(root: Path) -> None:
    for relative, encoded in PAYLOADS.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))


def _patch_waveform(root: Path) -> None:
    analyze = root / "waveform_analysis/scripts/analyze_ctr.py"
    _replace_once(analyze, R["analyze_imports_old"], R["analyze_imports_new"])
    _replace_once(analyze, "    plot_best_fit,\n", "")
    _replace_once(
        analyze,
        'plot_best_fit(best_led, args.output / "best_led_fit.png", dpi=dpi)',
        'plot_gaussian_fit(best_led, args.output / "best_led_fit.png", dpi=dpi)',
    )
    _replace_once(
        analyze,
        'plot_best_fit(best_cfd, args.output / "best_cfd_fit.png", dpi=dpi)',
        'plot_gaussian_fit(best_cfd, args.output / "best_cfd_fit.png", dpi=dpi)',
    )

    plots = root / "waveform_analysis/utils/plots.py"
    _replace_once(plots, "from .fit import FitResult\n", "")
    _regex_once(
        plots,
        r"\ndef plot_best_fit\(result: FitResult, path: Path, \*, dpi: int\) -> None:\n.*?(?=\ndef plot_toa_for_parameter\()",
        "",
    )

    metrics = root / "waveform_analysis/ml_pipeline/metrics.py"
    _replace_once(metrics, R["metrics_import_old"], R["metrics_import_new"])
    _regex_once(
        metrics,
        r"def fit_times_ps\(values_ps: np\.ndarray, method: str, fit_config: dict\[str, Any\]\) -> FitResult:\n.*?\n(?=def distribution_metrics\()",
        R["metrics_fit_new"],
    )

    study = root / "waveform_analysis/ml_pipeline/study.py"
    _replace_once(study, "from utils.fit import FitResult\n", "")
    _replace_once(
        study,
        "from .metrics import FWHM_PER_SIGMA, ctr_bootstrap_uncertainty, fit_times_ps, residual_metrics\n",
        "from .metrics import FitResult, FWHM_PER_SIGMA, ctr_bootstrap_uncertainty, fit_times_ps, residual_metrics\n",
    )

    legacy = root / "waveform_analysis/utils/fit.py"
    if legacy.exists():
        legacy.unlink()


def _patch_janus(root: Path) -> None:
    pipeline = root / "janus_data_analysis/utils/pipeline.py"
    _replace_once(pipeline, R["janus_import_old"], R["janus_import_new"])
    _replace_once(
        pipeline,
        "from .fitting import fit_timing, load_fit_csv, write_fit_csv\n",
        "",
    )
    _replace_once(pipeline, "    plot_timing_fit,\n", "")
    _replace_once(
        pipeline,
        '    "T_th",\n    "gaussian_area_events",\n',
        '    "T_th",\n    "fit_metric",\n    "gaussian_area_events",\n',
    )
    _regex_once(
        pipeline,
        r"def _summary_row\(run, run_info, fit, toa_lsb_ps: float\| None, average_delay_corrected_alignments: int\) -> dict\[str, Any\]:\n.*?\n    return row\n",
        R["janus_summary_new"],
    )
    _replace_once(pipeline, R["janus_fit_old"], R["janus_fit_new"])
    _replace_once(pipeline, R["janus_plot_old"], R["janus_plot_new"])

    plotting = root / "janus_data_analysis/utils/plotting.py"
    _replace_once(plotting, "    FitResult,\n", "")
    _regex_once(
        plotting,
        r"\ndef plot_timing_fit\(\n.*?(?=\ndef _matching_annotation\()",
        "",
    )

    models = root / "janus_data_analysis/utils/models.py"
    _regex_once(
        models,
        r"\n@dataclass\(slots=True, frozen=True\)\nclass FitResult:\n.*\Z",
        "\n",
    )

    cfg_path = root / "janus_data_analysis/config/janus_pipeline.json"
    cfg = json.loads(cfg_path.read_text(encoding="utf-8"))
    cfg["fit"] = COMMON_FIT_CONFIG
    cfg.setdefault("tasks", {}).setdefault("fit", {})["overwrite"] = True
    cfg.setdefault("plots", {}).setdefault("timing_fit", {})["overwrite"] = True
    cfg_path.write_text(json.dumps(cfg, indent=2) + "\n", encoding="utf-8")

    legacy = root / "janus_data_analysis/utils/fitting.py"
    if legacy.exists():
        legacy.unlink()


def _audit(root: Path) -> list[str]:
    problems = []
    forbidden = (
        "from utils.fit import",
        "from .fit import FitResult",
        "from .fitting import",
        "plot_timing_fit(",
        "def plot_best_fit(",
    )
    for path in root.rglob("*.py"):
        if ".git" in path.parts or "__pycache__" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for token in forbidden:
            if token in text:
                problems.append(f"{path.relative_to(root)}: leftover {token!r}")
    return problems


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Apply the common CTR Gaussian-fit refactor"
    )
    parser.add_argument("repo", type=Path)
    args = parser.parse_args()
    root = args.repo.resolve()

    if not (root / "waveform_analysis").is_dir() or not (
        root / "janus_data_analysis"
    ).is_dir():
        raise SystemExit(f"{root} does not look like the target repository")

    _write_payloads(root)
    _patch_waveform(root)
    _patch_janus(root)

    leftovers = _audit(root)
    print("Unified CTR-fit patch applied.")
    print("Created: utils_fit/ and compare_pico_waveform_ctr.py")
    print("Deleted: waveform_analysis/utils/fit.py")
    print("Deleted: janus_data_analysis/utils/fitting.py")
    if leftovers:
        print("\nManual references remain:")
        for item in leftovers:
            print("  " + item)
        raise SystemExit(2)

    print("\nRun:")
    print("  git diff --check")
    print(
        "  python -m compileall utils_fit waveform_analysis "
        "janus_data_analysis compare_pico_waveform_ctr.py"
    )
    print("  git status")
    print("\nThen rerun Janus before using summary.csv for comparison.")


if __name__ == "__main__":
    main()
